  "Tap the link to watch it light up the sky": "ఆకాశం వెలగడం చూడటానికి లింక్ ట్యాప్ చేయండి",
  "Tap the sky lanterns to burst them with fireworks": "ఆకాశ లాంతర్లను బాణసంచాతో పేల్చడానికి వాటిని ట్యాప్ చేయండి",
  "Tap the stars, it takes a second": "నక్షత్రాలు ట్యాప్ చేయండి, ఒక్క సెకను పడుతుంది",
  "Tap to change": "మార్చడానికి ట్యాప్ చేయండి",
  "Tap to open": "తెరవడానికి ట్యాప్ చేయండి",
  "Tap “Play the show”, then “Save video” to share it.": "షేర్ చేయడానికి “షో ప్లే చేయి”, తర్వాత “వీడియో సేవ్ చేయి” ట్యాప్ చేయండి.",
  "Tell others what you light up": "మీరు ఎవరిని వెలిగిస్తున్నారో ఇతరులకు చెప్పండి",
  "Temple jewels": "ఆలయ ఆభరణాలు",
  "Terms of Use": "వినియోగ నిబంధనలు",
  "Thanjavur": "తంజావూరు",
  "Thank You": "ధన్యవాదాలు",
  "Thank you for the lovely wishes! Sending a sky full of light right back to you.": "మంచి శుభాకాంక్షలకు ధన్యవాదాలు! మీకు తిరిగి వెలుగుతో నిండిన ఆకాశం పంపుతున్నాను.",
  "Thank you,": "ధన్యవాదాలు,",
  "That code isn’t valid": "ఆ కోడ్ చెల్లదు",
  "The app reads the names, birthdays and photos of contacts that have a birthday, so it can remind you. They stay on this phone and are never uploaded.": "మీకు గుర్తు చేయడానికి, పుట్టినరోజు ఉన్న కాంటాక్ట్స్ పేర్లు, పుట్టినరోజులు, ఫోటోలను యాప్ చదువుతుంది. అవి ఈ ఫోన్‌లోనే ఉంటాయి, ఎప్పుడూ అప్‌లోడ్ కావు.",
  "The bigger crackers cost gems. Everyday crackers and sparkler writing are always free.": "పెద్ద టపాసులకు జెమ్స్ కావాలి. రోజువారీ టపాసులు, కాకరపువ్వొత్తి రాత ఎప్పుడూ ఉచితమే.",
  "The camera is busy. Using the camera view instead.": "కెమెరా బిజీగా ఉంది. బదులుగా కెమెరా వ్యూ వాడుతున్నాం.",
  "The headline flies across the sky; the message appears on the card.": "శీర్షిక ఆకాశంలో ఎగురుతుంది; సందేశం కార్డుపై కనిపిస్తుంది.",
  "The link contains the whole card, so nothing is uploaded. Anyone who opens it sees the show.": "లింక్‌లోనే మొత్తం కార్డు ఉంటుంది, కాబట్టి ఏదీ అప్‌లోడ్ కాదు. దాన్ని తెరిచిన ఎవరైనా షో చూడగలరు.",
  "The link contains the whole card, so nothing is uploaded. Host the game online (for example GitHub Pages or Netlify) so friends can open the link.": "లింక్‌లోనే మొత్తం కార్డు ఉంటుంది, కాబట్టి ఏదీ అప్‌లోడ్ కాదు. స్నేహితులు లింక్ తెరవగలిగేలా గేమ్‌ను ఆన్‌లైన్‌లో హోస్ట్ చేయండి (ఉదాహరణకు GitHub Pages లేదా Netlify).",
  "The sky is full of light. Burst it first!": "ఆకాశం వెలుగుతో నిండిపోయింది. ముందు దాన్ని పేల్చండి!",
