  "Unlimited hints with Premium": "Premiumతో అపరిమిత సూచనలు",
  "Never get stuck in Diya Path or Rocket Rush. Plus no ads and every cracker free.": "దీపాల దారి లేదా రాకెట్ రష్‌లో ఎప్పుడూ ఆగిపోరు. అదనంగా ప్రకటనలు ఉండవు, ప్రతి టపాసు ఉచితం.",
