  "Every cracker free with Premium": "Premiumతో ప్రతి టపాసు ఉచితం",
  "Finales, cakes and rocket combos with no gems, plus no ads and unlimited puzzle hints.": "ఫినాలే, కేక్, రాకెట్ కాంబో జెమ్స్ లేకుండానే, అదనంగా ప్రకటనలు ఉండవు, అపరిమిత పజిల్ సూచనలు.",
  "No banners or videos, every cracker free, and unlimited puzzle hints.": "బ్యానర్లు, వీడియోలు ఉండవు, ప్రతి టపాసు ఉచితం, అపరిమిత పజిల్ సూచనలు.",
  "No ads. Every cracker. Every level.": "ప్రకటనలు లేవు. ప్రతి టపాసు. ప్రతి లెవెల్.",
  "One payment of {0}, charged to your {1} when you confirm. Not a subscription: nothing renews, and Premium is yours to keep. Restore it on a new phone with the same account.": "{0} ఒకేసారి చెల్లింపు, మీరు నిర్ధారించగానే మీ {1} నుండి తీసుకుంటారు. ఇది సబ్‌స్క్రిప్షన్ కాదు: ఏదీ రెన్యూ కాదు, Premium ఎప్పటికీ మీదే. అదే ఖాతాతో కొత్త ఫోన్‌లో రీస్టోర్ చేయండి.",
