  "Golden diyas and royal boards": "బంగారు దీపాలు, రాజసమైన బోర్డులు",
  "Premium dresses Diya Path in gold, with palace, river ghat and temple boards. Plus no ads and every cracker free.": "Premium దీపాల దారిని బంగారంతో అలంకరిస్తుంది, రాజభవనం, నదీ ఘాట్, ఆలయం బోర్డులతో. అదనంగా ప్రకటనలు ఉండవు, ప్రతి టపాసు ఉచితం.",
  "Golden diyas & royal boards": "బంగారు దీపాలు & రాజసమైన బోర్డులు",
  "All styles": "అన్ని స్టైల్స్",
  "India’s landmarks in 3D": "భారత స్మారకాలు 3Dలో",
  "Walk the forecourt of all 15 landmarks in 3D and look around as the fireworks burst. Plus no ads and every cracker free.": "మొత్తం 15 స్మారకాల ప్రాంగణంలో 3Dలో తిరగండి, టపాసులు పేలుతుండగా చుట్టూ చూడండి. అదనంగా ప్రకటనలు ఉండవు, ప్రతి టపాసు ఉచితం.",
  "Fireworks in your room with AR": "AR తో మీ గదిలోనే బాణసంచా",
  "Point your camera and light crackers on your own floor and sky. Plus no ads and every cracker free.": "కెమెరా చూపించి, మీ సొంత నేలపై, ఆకాశంలో టపాసులు కాల్చండి. దానితో పాటు ప్రకటనలు లేవు, ప్రతి టపాసూ ఉచితం.",
  "Sacred backgrounds for Diya Path": "దీపాల దారికి పవిత్ర నేపథ్యాలు",
  "Play before Lakshmi, Ganesha, Balaji, the Golden Temple and more. Plus no ads and every cracker free.": "లక్ష్మి, గణేశుడు, బాలాజీ, స్వర్ణ దేవాలయం మరెన్నో ముందు ఆడండి. దానితో పాటు ప్రకటనలు లేవు, ప్రతి టపాసూ ఉచితం.",
  "Couldn’t load the plans from the store. Check you’re signed in and online, then try again.": "స్టోర్ నుండి ప్లాన్‌లను లోడ్ చేయలేకపోయాం. మీరు సైన్ ఇన్ అయి ఆన్‌లైన్‌లో ఉన్నారో చూసి మళ్లీ ప్రయత్నించండి.",
  "See what Premium adds": "Premium ఏమి జోడిస్తుందో చూడండి",
  "Sacred backgrounds": "పవిత్ర నేపథ్యాలు",
  "Play Diya Path before Lakshmi, Ganesha, Balaji and more": "లక్ష్మి, గణేశుడు, బాలాజీ మరెన్నో ముందు దీపాల దారి ఆడండి",
  "Sacred backgrounds: Lakshmi, Ganesha, Balaji and more": "పవిత్ర నేపథ్యాలు: లక్ష్మి, గణేశుడు, బాలాజీ మరెన్నో",
  "All 10": "మొత్తం 10",
  "AR fireworks and sparkler in your room": "మీ గదిలో AR బాణసంచా మరియు చిచ్చుబుడ్డి",
  "Free for everyone and included with every plan.": "అందరికీ ఉచితం, ప్రతి ప్లాన్‌లోనూ ఉంటుంది.",
  "AR pictures are illustrations; the look on your phone depends on your camera and room. AR crackers on your real floor need a phone that supports Google Play Services for AR.": "AR చిత్రాలు ఉదాహరణలు; మీ ఫోన్‌లో కనిపించే తీరు కెమెరా, గదిపై ఆధారపడుతుంది. నిజమైన నేలపై AR టపాసులకు Google Play Services for AR మద్దతు ఉన్న ఫోన్ కావాలి.",
  "15 landmarks in 3D, look around": "3Dలో 15 స్మారకాలు, చుట్టూ చూడండి",
  "2D & 3D": "2D & 3D",
