  "Kubera": "కుబేరుడు",
  "Balaji": "బాలాజీ",
  "Ganesha": "గణేశుడు",
  "Lakshmi Ganesha": "లక్ష్మీ గణేశ",
  "Mahavira": "మహావీరుడు",
  "Buddha": "బుద్ధుడు",
  "Church": "చర్చి",
  "Mosque": "మసీదు",
  "Map": "మ్యాప్",
