  "I admire how calm you stay under pressure": "ఒత్తిడిలో కూడా మీరు ప్రశాంతంగా ఉండటం నాకు నచ్చుతుంది",
  "I love our tea breaks and quick laughs between meetings": "మీటింగ్‌ల మధ్య టీ బ్రేకులూ, చిన్న నవ్వులూ నాకు చాలా ఇష్టం",
