  "Keep it, and every other cracker, free with Premium. No ads, and 1,000 levels each in Diya Path and Rocket Rush.": "దీన్ని, ఇంకా ప్రతి టపాసును, Premiumతో ఉచితంగా పొందండి. ప్రకటనలు లేవు, దీపాల దారి మరియు రాకెట్ రష్లో ఒక్కోదానిలో 1,000 లెవెల్స్.",
  "No ads, every cracker free and 1,000 levels each in Diya Path and Rocket Rush, all through the festival.": "ప్రకటనలు లేవు, ప్రతి టపాసు ఉచితం, దీపాల దారి మరియు రాకెట్ రష్లో ఒక్కోదానిలో 1,000 లెవెల్స్, పండుగ అంతా.",
  "Unlock 1,000 levels each in Diya Path and Rocket Rush": "దీపాల దారి మరియు రాకెట్ రష్లో ఒక్కోదానిలో 1,000 లెవెల్స్ తెరవండి",
  "No ads · every cracker free with Premium": "ప్రకటనలు లేవు · Premiumతో ప్రతి టపాసు ఉచితం",
  "Grand finales, 3D skylines, AR, and 1,000 levels each in Diya Path and Rocket Rush with unlimited hints.": "గ్రాండ్ ఫినాలేలు, 3D స్కైలైన్లు, AR, మరియు దీపాల దారి, రాకెట్ రష్లో ఒక్కోదానిలో 1,000 లెవెల్స్, అపరిమిత సూచనలతో.",
  "Premium makes every cracker free and opens 1,000 levels each in Diya Path and Rocket Rush with unlimited hints.": "Premium ప్రతి టపాసును ఉచితం చేసి, దీపాల దారి, రాకెట్ రష్లో ఒక్కోదానిలో 1,000 లెవెల్స్ తెరుస్తుంది, అపరిమిత సూచనలతో.",
