  "Five Premium crackers": "ఐదు Premium టపాసులు",
  "The thousand-cracker Hazaar ladi, saravedi, seven shot, double shot and Lakshmi vedi. One free try each.": "వెయ్యి టపాసుల వెయ్యి లడీ, సరవేడి, సెవెన్ షాట్, డబుల్ షాట్, లక్ష్మి బాంబు. ఒక్కొక్కదానికి ఒక ఉచిత ప్రయత్నం.",
  "Grand finales, wedding cakes, sutli bombs and more. One of each costs {0} without Premium.": "గ్రాండ్ ఫినాలే, వెడ్డింగ్ కేక్, సుత్లీ బాంబు ఇంకా ఎన్నో. Premium లేకుండా ఒక్కొక్కటి ఒకసారి కాల్చడానికి {0} కావాలి.",
  "A grand finale and a wedding cake every evening for a month: {0} (about {1} at gem-pack prices). With Premium they’re free, with everything above.": "ఒక నెల రోజూ సాయంత్రం ఒక గ్రాండ్ ఫినాలే, ఒక వెడ్డింగ్ కేక్: {0} (జెమ్ ప్యాక్ ధరలో సుమారు {1}). Premiumతో ఇవి ఉచితం, పైన ఉన్న అన్నిటితో పాటు.",
  "A grand finale and a wedding cake every evening for a month: {0}. With Premium they’re free, with everything above.": "ఒక నెల రోజూ సాయంత్రం ఒక గ్రాండ్ ఫినాలే, ఒక వెడ్డింగ్ కేక్: {0}. Premiumతో ఇవి ఉచితం, పైన ఉన్న అన్నిటితో పాటు.",
  "Light the {0} with Premium": "Premiumతో {0} వెలిగించండి",
  "Hazaar ladi, saravedi, seven shot, double shot and Lakshmi vedi, lit with your sparkler. Plus no ads and every cracker free.": "వెయ్యి లడీ, సరవేడి, సెవెన్ షాట్, డబుల్ షాట్, లక్ష్మి బాంబు, మీ కాకరపువ్వొత్తితో వెలిగించండి. దాంతో పాటు ప్రకటనలు లేవు, ప్రతి టపాసు ఉచితం.",
