  "Rare stash found! It counts for the race": "అరుదైన చోటు దొరికింది! ఇది రేస్‌లో లెక్కకు వస్తుంది",
  "Press Fire, or throw it: it lights as it flies. Bigger chaos, more points.": "ఫైర్ నొక్కండి, లేదా విసరండి: ఎగురుతూనే వెలుగుతుంది. ఎక్కువ హడావుడి, ఎక్కువ పాయింట్లు.",
  "Chaos: points for the mischief your crackers cause (near people, stalls, roofs, the donkey). Found: today’s hidden stashes on this street.": "హడావుడి: మీ టపాసుల అల్లరికి పాయింట్లు (మనుషులు, దుకాణాలు, పైకప్పులు, గాడిద దగ్గర). దొరికినవి: ఈ వీధిలో నేటి దాచిన చోట్లు.",
  "🏁 Home in {0} · waiting for the others": "🏁 {0}లో చేరారు · మిగతావారి కోసం ఎదురుచూపు",
  "Carry 10 kinds of cracker, not 6. Yours for good": "6 కాదు, 10 రకాల టపాసులు తీసుకెళ్లండి. ఎప్పటికీ మీదే",
