  "🚨 You have the {0}! RUN to the gate 🏁": "🚨 {0} మీ దగ్గర ఉంది! గేటుకు పరుగెత్తండి 🏁",
  "Seth-ji grabbed it! It fell at your feet. Snatch it back": "సేఠ్‌జీ లాక్కున్నాడు! అది మీ పాదాల దగ్గర పడింది. మళ్లీ పట్టుకోండి",
  "🏆 The {0} is yours! It's in your trophy room": "🏆 {0} మీదే! అది మీ ట్రోఫీ గదిలో ఉంది",
