  "🎭 Master Thief frame unlocked": "🎭 మాస్టర్ దొంగ ఫ్రేమ్ అన్‌లాక్ అయింది",
  "🎭 Master Thief frame: {0}/{1} heists": "🎭 మాస్టర్ దొంగ ఫ్రేమ్: {0}/{1} దొంగతనాలు",
